window.HOEREN_TESTS[8] = {"id":"sport-und-fitness","name":"Sport und Fitness","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Hallo Mitglieder vom Fitnessstudio Aktiv, eine wichtige Information: Der Gruppen-Kurs Spinning am Mittwochabend fällt diese Woche aus, weil der Trainer krank ist. Statt Spinning bieten wir Yoga in derselben Zeit an. Nicht alle Kurse fallen aus, und die Trainer bleiben auch. Wer Interesse hat, bitte am Empfang anmelden. Die anderen Kurse laufen normal weiter.","gender":"f","q":"Was ist die Änderung diese Woche?","opts":["Die Trainer wurden gewechselt.","Alle Kurse fallen aus.","Spinning wird durch Yoga ersetzt."],"correct":2},{"transcript":"Achtung an alle Schwimmer im Hallenbad. Das Schwimmbad schließt heute schon um 18 Uhr, statt um 22 Uhr. Wegen einer Veranstaltung am Abend können wir das Bad nicht länger offen halten. Morgen sind wir wieder zu den normalen Zeiten geöffnet. Wir bitten um Ihr Verständnis. Vielen Dank!","gender":"m","q":"Wann schließt das Schwimmbad heute?","opts":["Um 16 Uhr.","Um 22 Uhr.","Um 18 Uhr."],"correct":2},{"transcript":"Hi Anna, hier ist Trainer Marco. Dein Tennis-Termin morgen um 17 Uhr passt nicht mehr — der Platz ist gebucht. Ich biete dir 16 Uhr oder 19 Uhr an, beide gehen. Vielleicht ist 16 Uhr besser, weil du danach noch Zeit hast. Schreib mir kurz, was du nimmst. Danke!","gender":"m","q":"Wann schlägt der Trainer den Termin vor?","opts":["Um 17 Uhr wie geplant.","Um 16 Uhr oder 19 Uhr.","Erst nächste Woche."],"correct":1},{"transcript":"Liebe Sportfreunde, der Stadtlauf am Sonntag startet um 10 Uhr im Stadtpark. Die Strecke ist 10 Kilometer lang, durch die Innenstadt und entlang des Flusses. Zuschauer können besonders gut an der Brücke stehen — dort gibt es auch Verpflegung. Bei Regen findet der Lauf trotzdem statt — nur bei Gewitter wäre er abgesagt.","gender":"f","q":"Wann findet der Lauf nicht statt?","opts":["Bei Regen.","Bei Gewitter.","Bei Sonnenschein."],"correct":1},{"transcript":"Hallo Lukas, hier ist Maria. Unser gemeinsamer Lauf-Termin am Samstag morgen — wir treffen uns nicht im Park, sondern direkt an meinem Haus. Von dort laufen wir zum See, das sind etwa 5 Kilometer. Bitte sei pünktlich um 7 Uhr da. Sportzeug nicht vergessen, ein bisschen Wasser auch.","gender":"f","q":"Wo treffen sie sich?","opts":["Bei Maria zu Hause.","Im Park.","Direkt am See."],"correct":0}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch zwischen Anna und Lukas. Sie planen die Sport-Woche im Fitnessstudio. Sie hören den Text einmal. Was macht Anna an welchem Tag? Wählen Sie für jeden Tag einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Anna! Der neue Kursplan im Fitnessstudio hängt seit heute aus."},{"speaker":"Anna","gender":"f","text":"Zeig ihn mir bitte. Ich will an fünf Tagen trainieren und einen Tag frei bleiben."},{"speaker":"Lukas","gender":"m","text":"Die Geräte sind morgens noch fast frei. Wann nimmst du das Krafttraining?"},{"speaker":"Anna","gender":"f","text":"Das Krafttraining nehme ich am Montag. Das schaffe ich gut vor der Arbeit."},{"speaker":"Lukas","gender":"m","text":"Wolltest du diese Woche auch Tennis auf dem Platz spielen?"},{"speaker":"Anna","gender":"f","text":"Nein. Tennis spiele ich nicht. Der Platz bleibt bis zum Sommer belegt."},{"speaker":"Lukas","gender":"m","text":"Das Schwimmen im Becken tut dir nach der Arbeit gut. Wann passt das bei dir?"},{"speaker":"Anna","gender":"f","text":"Schwimmen gehe ich am Dienstag. Das Wasser ist abends angenehm ruhig."},{"speaker":"Lukas","gender":"m","text":"Und die ruhige Stunde auf der Matte bleibt auch im Plan?"},{"speaker":"Anna","gender":"f","text":"Pilates mache ich am Donnerstag. Die Stunde beginnt um sechs."},{"speaker":"Lukas","gender":"m","text":"Was hast du dir für das Joggen im Park vorgenommen?"},{"speaker":"Anna","gender":"f","text":"Joggen gehe ich am Freitag. Die Runde um den kleinen See ist schön lang."},{"speaker":"Lukas","gender":"m","text":"Spielst du auch Fußball in einem Verein?"},{"speaker":"Anna","gender":"f","text":"Nein. Fußball spiele ich nicht. Ich habe hier kein festes Team dafür."},{"speaker":"Lukas","gender":"m","text":"Bleibt der letzte Tag auch noch sportlich für dich?"},{"speaker":"Anna","gender":"f","text":"Fahrrad fahre ich am Samstag bis zum See. Die Strecke dort ist schön flach."},{"speaker":"Lukas","gender":"m","text":"Dann hänge ich den Plan an deinen Spiegel. Wir starten früh in die Woche."}],"options":[{"letter":"a","text":"Tennis spielen"},{"letter":"b","text":"Krafttraining"},{"letter":"c","text":"Yoga"},{"letter":"d","text":"Pilates"},{"letter":"e","text":"Fußball spielen"},{"letter":"f","text":"Klettern"},{"letter":"g","text":"Joggen"},{"letter":"h","text":"Fahrrad fahren"},{"letter":"i","text":"Schwimmen"}],"items":[{"person":"Montag","correct":"b"},{"person":"Dienstag","correct":"i"},{"person":"Donnerstag","correct":"d"},{"person":"Freitag","correct":"g"},{"person":"Samstag","correct":"h"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Verkäufer","gender":"m","text":"Welche Schuhe brauchen Sie?"},{"speaker":"Kundin","gender":"f","text":"Laufschuhe. Ich gehe joggen, aber im Wald, mit unebenem Boden."},{"speaker":"Verkäufer","gender":"m","text":"Dann brauchen Sie Trail-Schuhe, nicht normale Laufschuhe und keine Tennis-Schuhe. Die haben bessere Sohlen."},{"speaker":"Kundin","gender":"f","text":"Verstehe, ich nehme die. Haben Sie Größe 38?"},{"speaker":"Verkäufer","gender":"m","text":"Größe 38 haben wir da. Möchten Sie sie anprobieren?"}],"q":"Was kauft die Kundin?","opts":["Normale Laufschuhe.","Trail-Schuhe.","Tennis-Schuhe."],"correct":1},{"lines":[{"speaker":"Trainerin","gender":"f","text":"Was möchten Sie heute machen?"},{"speaker":"Schüler","gender":"m","text":"Mein Rücken tut weh seit gestern. Vielleicht keine starken Übungen heute."},{"speaker":"Trainerin","gender":"f","text":"Dann machen wir Dehnübungen und etwas Yoga. Keine Gewichte und kein Spinning heute."},{"speaker":"Schüler","gender":"m","text":"Perfekt, das tut mir gut. Danke schön!"},{"speaker":"Trainerin","gender":"f","text":"Gern! Und Spinning machen wir ein anderes Mal, einverstanden?"}],"q":"Was macht der Schüler heute?","opts":["Dehnübungen und Yoga.","Gewichte heben.","Spinning."],"correct":0},{"lines":[{"speaker":"Empfang","gender":"f","text":"Sie möchten Mitglied werden?"},{"speaker":"Kunde","gender":"m","text":"Ja, wie viel kostet das?"},{"speaker":"Empfang","gender":"f","text":"Monatsmitgliedschaft 39 Euro, Jahresmitgliedschaft 35 Euro pro Monat. Studenten zahlen 25."},{"speaker":"Kunde","gender":"m","text":"Ich bin Student. Aber Jahres ist mir zu lang. Monatlich, bitte."},{"speaker":"Empfang","gender":"f","text":"Mit Studentenausweis. 25 Euro pro Monat, das ist günstig."},{"speaker":"Kunde","gender":"m","text":"Gut, hier ist mein Ausweis. Wo unterschreibe ich? Hier?"}],"q":"Wie viel zahlt der Kunde pro Monat?","opts":["25 Euro.","35 Euro.","39 Euro."],"correct":0},{"lines":[{"speaker":"Trainer","gender":"m","text":"Wie war das Training?"},{"speaker":"Spielerin","gender":"f","text":"Anstrengend. Aber gut."},{"speaker":"Trainer","gender":"m","text":"Wir haben heute das nächste Spiel am Samstag um 15 Uhr. Bist du dabei?"},{"speaker":"Spielerin","gender":"f","text":"Samstag um 15 Uhr — leider nicht. Mein Bruder hat Hochzeit."},{"speaker":"Trainer","gender":"m","text":"Schade, aber Hochzeit ist Hochzeit. Viel Spaß am Samstag!"},{"speaker":"Spielerin","gender":"f","text":"Danke! Nächstes Spiel bin ich wieder dabei, versprochen!"}],"q":"Warum spielt sie nicht am Samstag?","opts":["Sie ist krank.","Anstrengung.","Hochzeit des Bruders."],"correct":2},{"lines":[{"speaker":"Vater","gender":"m","text":"Mama, willst du Sport mit mir machen?"},{"speaker":"Tochter","gender":"f","text":"Hmm, was?"},{"speaker":"Vater","gender":"m","text":"Ich gehe joggen. Oder ein Spaziergang, wenn du nicht laufen willst."},{"speaker":"Tochter","gender":"f","text":"Spaziergang ist gut. Joggen schaffe ich nicht mehr, Fahrrad auch nicht."},{"speaker":"Vater","gender":"m","text":"Gut, Spaziergang! Um drei am See, einverstanden?"},{"speaker":"Tochter","gender":"f","text":"Einverstanden! Bis drei, ich freue mich! Bis drei!"}],"q":"Was machen sie zusammen?","opts":["Joggen.","Fahrrad fahren.","Spazieren gehen."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Hoffmann, einer Fitness-Trainerin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Hoffmann, Sie sind seit 8 Jahren Fitness-Trainerin. Wie sind Sie zu diesem Beruf gekommen?"},{"speaker":"Hoffmann","gender":"f","text":"Ich war früher Profi-Sportlerin im Handball. Mit 28 musste ich wegen einer Verletzung aufhören. Trainerin sein war für mich der natürliche nächste Schritt — ich kenne Sport gut."},{"speaker":"Reporter","gender":"m","text":"Wer sind Ihre typischen Kunden?"},{"speaker":"Hoffmann","gender":"f","text":"Sehr unterschiedlich, junge Menschen, die mehr Muskeln wollen. Ältere, die fit bleiben wollen. Mütter, die wieder in Form kommen wollen nach dem Baby. Profi-Sportler kommen selten — die haben eigene Trainer."},{"speaker":"Reporter","gender":"m","text":"Was ist der größte Fehler beim Anfangen?"},{"speaker":"Hoffmann","gender":"f","text":"Zu viel auf einmal! Anfänger denken, sie müssen jeden Tag trainieren, sonst funktioniert es nicht. Aber Pause-Tage sind genauso wichtig wie Training. Erholung ist nicht Faulheit."},{"speaker":"Reporter","gender":"m","text":"Was essen Sie selbst?"},{"speaker":"Hoffmann","gender":"f","text":"Normal — keine spezielle Diät. Viel Gemüse und Obst, ja, aber auch ein Stück Kuchen, wenn ich Lust habe. Das Wichtigste: regelmäßig essen und genug Wasser trinken."},{"speaker":"Reporter","gender":"m","text":"Was machen Sie in Ihrer Freizeit?"},{"speaker":"Hoffmann","gender":"f","text":"Lesen! Romane, vor allem alte. Ich gehe nicht ins Fitnessstudio in meiner Freizeit — das wäre wie Arbeit. Spazieren mit meinem Hund, ja, das mache ich gern."}],"items":[{"q":"Frau Hoffmann war früher Tennis-Spielerin.","correct":"nein"},{"q":"Profi-Sportler trainieren oft bei ihr.","correct":"nein"},{"q":"Pause-Tage sind wichtig fürs Training.","correct":"ja"},{"q":"Sie isst keine Süßigkeiten.","correct":"nein"},{"q":"In ihrer Freizeit liest sie gern.","correct":"ja"}]}]};
